pointLocator.script:
time_polling_min = 1;
time_polling_seg = time_polling_min * 60;
time_polling_ms = time_polling_seg * 1000;

try{
    if(measure001.time == null){
        status001.set(0.0);
    } else{
        if(Date.now() - measure001.time > time_polling_ms){
            status001.set(0.0);
        } else{
            status001.set(1.0);
        }
    }
} catch(e){
   status001.set(0.0);
}

return 1
